import{_ as i,o as a,c as s,ae as t}from"./chunks/framework.FQ5RHm_v.js";const h=JSON.parse('{"title":"wvke-sdk | Personnalisation Parfaite !","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | Personnalisation Parfaite !","titleTemplate":false},"headers":[],"relativePath":"fr/index.md","filePath":"fr/index.md"}'),l={name:"fr/index.md"};function r(o,e,n,d,u,c){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk est un SDK JavaScript pour communiquer avec les périphériques gaming, y compris les claviers et les souris.</p><p>Construit sur la technologie moderne WebHID, il permet une personnalisation approfondie et un contrôle intelligent des claviers, souris et autres périphériques. Il accélère la livraison de bout en bout des produits périphériques gaming et ouvre de nouvelles possibilités dans l&#39;écosystème gaming. Le projet est développé et maintenu par le GDE Game Driver Engine Team.</p><h2 id="types-de-sdk" tabindex="-1">Types de SDK <a class="header-anchor" href="#types-de-sdk" aria-label="Permalink to &quot;Types de SDK&quot;">​</a></h2><h3 id="⌨️-clavier-lineaire" tabindex="-1">⌨️ Clavier linéaire <a class="header-anchor" href="#⌨️-clavier-lineaire" aria-label="Permalink to &quot;⌨️ Clavier linéaire&quot;">​</a></h3><p>Conçu pour les claviers mécaniques :</p><ul><li>Mappage des touches et changement de couche</li><li>Contrôle d&#39;éclairage RGB</li><li>Autorisation WebHID, liste des appareils autorisés et initialisation</li><li>Interrupteur de course complète RT, réglage de course et zone de sécurité</li><li>Enregistrement et lecture de macros</li><li>Réglage du taux d&#39;interrogation (1KHz-8KHz)</li><li>Changement de mode système (Windows/Mac)</li></ul><h3 id="🖱️-sdk-souris" tabindex="-1">🖱️ SDK Souris <a class="header-anchor" href="#🖱️-sdk-souris" aria-label="Permalink to &quot;🖱️ SDK Souris&quot;">​</a></h3><p>Conçu pour les souris gaming :</p><ul><li>Réglage DPI (400-16000 DPI)</li><li>Programmation des boutons et macros</li><li>Personnalisation de l&#39;éclairage RGB</li><li>Réglage de la distance de décollage</li><li>Optimisation de l&#39;interrogation</li></ul><h2 id="caracteristiques" tabindex="-1">Caractéristiques <a class="header-anchor" href="#caracteristiques" aria-label="Permalink to &quot;Caractéristiques&quot;">​</a></h2><ul><li>Support JavaScript/TypeScript moderne</li><li>Communication matérielle WebHID</li><li>APIs complètes de contrôle d&#39;éclairage</li><li>APIs de mappage des touches et macros</li><li>APIs de course RT, touches avancées et initialisation</li><li>APIs DPI et mappage des boutons de souris</li><li>Service de mise à jour personnalisée générale</li><li>Documentation API détaillée</li></ul><h2 id="tutoriel" tabindex="-1">Tutoriel <a class="header-anchor" href="#tutoriel" aria-label="Permalink to &quot;Tutoriel&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>Consultez la <a href="/wvke.sdkdoc/docs/fr/api/info.html">documentation API</a> pour plus de détails.</p>',15)])])}const m=i(l,[["render",r]]);export{h as __pageData,m as default};
